To fix issue #7847 I have done the following changes to the code in sympy/sympy/printing/str.py
Will this work?
class StrPrinter(Printer):
    printmethod = "_sympystr"
    _default_settings = {
        "order": None,
        "full_prec": "auto",
        "min": None,
        "max": None,
    }
def _print_Float(self, expr):
        prec = expr._prec
        low = self._settings["min"]
        high = self._settings["max"]
        if prec < 5:
            dps = 0
        else:
            dps = prec_to_dps(expr._prec) 
        if self._settings["full_prec"] is True:
            strip = False
        elif self._settings["full_prec"] is False:
            strip = True
        elif self._settings["full_prec"] == "auto":
            strip = self._print_level > 1
        if low is None:
            low = min(-(dps//3), -5)
        if high is None:
            high = dps
        rv = mlib.to_str(expr._mpf_, dps, strip_zeros=strip, min_fixed=low, max_fixed=high)
        if rv.startswith('-.0'):
            rv = '-0.' + rv[3:]
        elif rv.startswith('.0'):
            rv = '0.' + rv[2:]
        return rv

